/* الفلترة حسب قيمة #filter: all يعرض الجميع، وإلا الفئة المطابقة فقط */
function getFiltered() {
  var filterValue = filterSelect.value;
  if (filterValue === 'all') return expenses;
  return expenses.filter(function (item) { return item.category === filterValue; });
}

function computeTotal(list) {
  return list.reduce(function (sum, item) { return sum + item.amount; }, 0);
}

