/* إعادة رسم القائمة والمجموع بعد كل تغيير.
   #entries يعرض العناصر المطابقة للفلتر فقط، و#total يحسب مجموع المعروض فقط */
function render() {
  var visible = getFiltered();

  entriesList.textContent = '';
  if (visible.length === 0) {
    var empty = document.createElement('li');
    empty.className = 'empty';
    empty.textContent = (expenses.length === 0)
      ? 'لا توجد مصروفات بعد — أضف أول مصروف من النموذج أعلاه.'
      : 'لا توجد مصروفات في هذه الفئة.';
    entriesList.appendChild(empty);
  } else {
    visible.forEach(function (item) {
      entriesList.appendChild(buildEntry(item));
    });
  }
  totalEl.textContent = formatAmount(computeTotal(visible));
  countEl.textContent = String(visible.length);
}

